Delay(0.1, {this.black_hole = FindClosestObject( 'Metadata/Effects/Microtransactions/Misc/uniques/BlackHole/blackhole' ); this.black_hole_position = black_hole.GetPositionValues(  );
		this.position = this.GetPositionValues(  );
		this.sopx = black_hole_position[0] - position[0];
		this.on_kill_black_hole_position += sopx;
		this.sopy = black_hole_position[1] - position[1];
		this.on_kill_black_hole_position += sopy;
		this.sopz = black_hole_position[2] - position[2];
		this.on_kill_black_hole_position += sopz; });
